# SwiftUI: Building Production-Ready iOS Apps

SwiftUI is Apple's modern declarative framework for building user interfaces across all Apple platforms. This guide covers advanced patterns for production apps.

## Why SwiftUI?

- **Declarative Syntax**: Describe what UI should look like
- **Cross-Platform**: iOS, macOS, watchOS, tvOS
- **Live Previews**: See changes instantly
- **Less Code**: No storyboards, no AutoLayout constraints
- **Built-in Accessibility**: Automatic VoiceOver support

## State Management

### @State for Local State

```swift
struct CounterView: View {
    @State private var count = 0

    var body: some View {
        VStack {
            Text("Count: \(count)")
                .font(.largeTitle)

            HStack {
                Button("-") { count -= 1 }
                Button("+") { count += 1 }
            }
            .buttonStyle(.bordered)
        }
    }
}
```

### @Binding for Two-Way Data Flow

```swift
// Parent view
struct ParentView: View {
    @State private var isOn = false

    var body: some View {
        ToggleView(isOn: $isOn)
    }
}

// Child view - receives binding
struct ToggleView: View {
    @Binding var isOn: Bool

    var body: some View {
        Toggle("Enable Feature", isOn: $isOn)
    }
}
```

### @StateObject and @ObservedObject

```swift
// ViewModel
class UserViewModel: ObservableObject {
    @Published var users: [User] = []
    @Published var isLoading = false
    @Published var errorMessage: String?

    func fetchUsers() async {
        isLoading = true
        defer { isLoading = false }

        do {
            users = try await APIService.shared.getUsers()
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

// View that owns the ViewModel
struct UserListView: View {
    @StateObject private var viewModel = UserViewModel()

    var body: some View {
        List(viewModel.users) { user in
            UserRow(user: user)
        }
        .overlay {
            if viewModel.isLoading {
                ProgressView()
            }
        }
        .task {
            await viewModel.fetchUsers()
        }
    }
}

// Child view - receives ViewModel
struct UserDetailView: View {
    @ObservedObject var viewModel: UserViewModel
    let userId: String

    var body: some View {
        // Use viewModel
    }
}
```

### @EnvironmentObject for App-Wide State

```swift
// App-wide state
class AppState: ObservableObject {
    @Published var user: User?
    @Published var isLoggedIn = false
    @Published var theme: AppTheme = .system
}

// Inject at app level
@main
struct MyApp: App {
    @StateObject private var appState = AppState()

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environmentObject(appState)
        }
    }
}

// Access anywhere in the view hierarchy
struct ProfileView: View {
    @EnvironmentObject var appState: AppState

    var body: some View {
        if let user = appState.user {
            Text("Welcome, \(user.name)")
        } else {
            LoginView()
        }
    }
}
```

## Custom View Modifiers

```swift
// Define custom modifier
struct CardModifier: ViewModifier {
    func body(content: Content) -> some View {
        content
            .padding()
            .background(Color(.systemBackground))
            .cornerRadius(12)
            .shadow(color: .black.opacity(0.1), radius: 5, x: 0, y: 2)
    }
}

// Extension for easy access
extension View {
    func cardStyle() -> some View {
        modifier(CardModifier())
    }
}

// Usage
struct ContentView: View {
    var body: some View {
        Text("Hello, World!")
            .cardStyle()
    }
}
```

### Conditional Modifiers

```swift
extension View {
    @ViewBuilder
    func `if`<Transform: View>(
        _ condition: Bool,
        transform: (Self) -> Transform
    ) -> some View {
        if condition {
            transform(self)
        } else {
            self
        }
    }
}

// Usage
Text("Hello")
    .if(isHighlighted) { view in
        view.foregroundColor(.yellow)
    }
```

## Navigation

### NavigationStack (iOS 16+)

```swift
struct ContentView: View {
    @State private var path = NavigationPath()

    var body: some View {
        NavigationStack(path: $path) {
            List {
                NavigationLink("Go to Detail", value: "detail")
                NavigationLink("Go to Settings", value: SettingsRoute.general)
            }
            .navigationTitle("Home")
            .navigationDestination(for: String.self) { value in
                DetailView(id: value)
            }
            .navigationDestination(for: SettingsRoute.self) { route in
                SettingsView(route: route)
            }
        }
    }
}

enum SettingsRoute: Hashable {
    case general
    case privacy
    case notifications
}
```

### Programmatic Navigation

```swift
struct HomeView: View {
    @State private var path = NavigationPath()

    var body: some View {
        NavigationStack(path: $path) {
            VStack {
                Button("Go to Profile") {
                    path.append("profile")
                }

                Button("Deep Link") {
                    path.append("settings")
                    path.append("privacy")
                }
            }
            .navigationDestination(for: String.self) { value in
                Text("Page: \(value)")
            }
        }
    }
}
```

## Async/Await Integration

```swift
struct AsyncImageList: View {
    @State private var images: [ImageItem] = []
    @State private var isLoading = true

    var body: some View {
        List(images) { image in
            AsyncImage(url: URL(string: image.url)) { phase in
                switch phase {
                case .empty:
                    ProgressView()
                case .success(let image):
                    image
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                case .failure:
                    Image(systemName: "photo")
                        .foregroundColor(.gray)
                @unknown default:
                    EmptyView()
                }
            }
            .frame(height: 200)
            .clipped()
        }
        .task {
            await loadImages()
        }
        .refreshable {
            await loadImages()
        }
    }

    func loadImages() async {
        isLoading = true
        defer { isLoading = false }

        do {
            images = try await APIService.shared.fetchImages()
        } catch {
            print("Error: \(error)")
        }
    }
}
```

## Animations

### Basic Animations

```swift
struct AnimationDemo: View {
    @State private var isExpanded = false

    var body: some View {
        VStack {
            Rectangle()
                .fill(.blue)
                .frame(width: isExpanded ? 200 : 100,
                       height: isExpanded ? 200 : 100)
                .animation(.spring(response: 0.5, dampingFraction: 0.6), value: isExpanded)

            Button("Toggle") {
                isExpanded.toggle()
            }
        }
    }
}
```

### Transitions

```swift
struct TransitionDemo: View {
    @State private var showDetail = false

    var body: some View {
        VStack {
            Button("Toggle") {
                withAnimation(.easeInOut(duration: 0.3)) {
                    showDetail.toggle()
                }
            }

            if showDetail {
                DetailCard()
                    .transition(.asymmetric(
                        insertion: .move(edge: .trailing).combined(with: .opacity),
                        removal: .move(edge: .leading).combined(with: .opacity)
                    ))
            }
        }
    }
}
```

### Custom Animations

```swift
struct PulseAnimation: View {
    @State private var isPulsing = false

    var body: some View {
        Circle()
            .fill(.blue)
            .frame(width: 100, height: 100)
            .scaleEffect(isPulsing ? 1.2 : 1.0)
            .opacity(isPulsing ? 0.8 : 1.0)
            .animation(
                .easeInOut(duration: 1.0)
                .repeatForever(autoreverses: true),
                value: isPulsing
            )
            .onAppear {
                isPulsing = true
            }
    }
}
```

## Lists and Forms

### Advanced List

```swift
struct TaskListView: View {
    @State private var tasks: [Task] = Task.samples
    @State private var selection = Set<Task.ID>()

    var body: some View {
        List(selection: $selection) {
            ForEach($tasks) { $task in
                TaskRow(task: $task)
                    .swipeActions(edge: .trailing) {
                        Button(role: .destructive) {
                            deleteTask(task)
                        } label: {
                            Label("Delete", systemImage: "trash")
                        }
                    }
                    .swipeActions(edge: .leading) {
                        Button {
                            task.isCompleted.toggle()
                        } label: {
                            Label(
                                task.isCompleted ? "Undo" : "Complete",
                                systemImage: task.isCompleted ? "arrow.uturn.left" : "checkmark"
                            )
                        }
                        .tint(task.isCompleted ? .orange : .green)
                    }
            }
            .onMove(perform: move)
            .onDelete(perform: delete)
        }
        .toolbar {
            EditButton()
        }
    }
}
```

### Forms

```swift
struct SettingsForm: View {
    @State private var username = ""
    @State private var notificationsEnabled = true
    @State private var selectedTheme = Theme.system
    @State private var fontSize = 14.0

    var body: some View {
        Form {
            Section("Profile") {
                TextField("Username", text: $username)

                LabeledContent("Email") {
                    Text("user@example.com")
                        .foregroundColor(.secondary)
                }
            }

            Section("Preferences") {
                Toggle("Enable Notifications", isOn: $notificationsEnabled)

                Picker("Theme", selection: $selectedTheme) {
                    ForEach(Theme.allCases) { theme in
                        Text(theme.rawValue).tag(theme)
                    }
                }

                Slider(value: $fontSize, in: 12...24, step: 1) {
                    Text("Font Size")
                } minimumValueLabel: {
                    Text("12")
                } maximumValueLabel: {
                    Text("24")
                }
            }

            Section {
                Button("Save Changes") {
                    saveSettings()
                }
                .frame(maxWidth: .infinity)
            }
        }
        .navigationTitle("Settings")
    }
}
```

## Error Handling

```swift
struct ErrorHandlingView: View {
    @State private var result: Result<[User], Error>?
    @State private var showingAlert = false
    @State private var alertMessage = ""

    var body: some View {
        Group {
            switch result {
            case .none:
                ProgressView()
            case .success(let users):
                List(users) { user in
                    Text(user.name)
                }
            case .failure(let error):
                ContentUnavailableView(
                    "Unable to Load",
                    systemImage: "wifi.slash",
                    description: Text(error.localizedDescription)
                )
            }
        }
        .task {
            await loadData()
        }
        .alert("Error", isPresented: $showingAlert) {
            Button("OK") { }
            Button("Retry") {
                Task { await loadData() }
            }
        } message: {
            Text(alertMessage)
        }
    }

    func loadData() async {
        do {
            let users = try await APIService.shared.getUsers()
            result = .success(users)
        } catch {
            result = .failure(error)
        }
    }
}
```

## Best Practices

### 1. Use Proper Property Wrappers

```swift
// @State - Simple value types owned by view
@State private var count = 0

// @StateObject - ObservableObject owned by view
@StateObject private var viewModel = ViewModel()

// @ObservedObject - ObservableObject passed from parent
@ObservedObject var viewModel: ViewModel

// @EnvironmentObject - Shared state from environment
@EnvironmentObject var appState: AppState

// @Binding - Two-way connection to parent's state
@Binding var isPresented: Bool
```

### 2. Extract Reusable Components

```swift
// Reusable button style
struct PrimaryButtonStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .padding()
            .frame(maxWidth: .infinity)
            .background(Color.accentColor)
            .foregroundColor(.white)
            .cornerRadius(10)
            .scaleEffect(configuration.isPressed ? 0.95 : 1.0)
    }
}

// Usage
Button("Submit") { }
    .buttonStyle(PrimaryButtonStyle())
```

### 3. Use Preview Providers

```swift
#Preview {
    UserProfileView(user: .preview)
}

#Preview("Dark Mode") {
    UserProfileView(user: .preview)
        .preferredColorScheme(.dark)
}

#Preview("Large Text") {
    UserProfileView(user: .preview)
        .environment(\.sizeCategory, .accessibilityLarge)
}
```

## Summary

1. ✅ Choose correct property wrappers
2. ✅ Use NavigationStack for navigation
3. ✅ Leverage async/await for data loading
4. ✅ Create custom view modifiers
5. ✅ Add animations for polish
6. ✅ Handle errors gracefully
7. ✅ Test with previews

## Conclusion

SwiftUI enables rapid iOS development with powerful declarative syntax. Master state management and custom components to build production-ready apps.

Happy SwiftUI coding!
